<?php require_once __DIR__.'/config/auth.php';require_admin();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('payments_list.php');verify_csrf();$id=(int)($_POST['id']??0);$s=db()->prepare('SELECT archive_id FROM payments WHERE id=?');$s->execute([$id]);$p=$s->fetch();if($p){$s=db()->prepare('DELETE FROM payments WHERE id=?');$s->execute([$id]);flash('success','Payment deleted.');redirect('archive_view.php?id='.$p['archive_id']);}flash('error','Payment not found.');redirect('payments_list.php');
